{"script":"
() => {
  const allElements = document.querySelectorAll('[class*="ingredient"]');
  const results = [];
  allElements.forEach(el => {
    if (el.textContent && el.textContent.length < 200) {
      results.push({tag: el.tagName, class: el.className, text: el.textContent.trim().replace(/\s+/g, ' ')});
    }
  });
  return results.slice(0, 20);
}"}

